SELECT m.CSNAME AS `股票名称`, m.COMB_SYMBOL AS `股票代码`, ROUND(MAX(CASE WHEN c.F056N = 2025 THEN c.F048N END) / 100, 3) AS `2025财年营业收入(亿美元)`, ROUND(MAX(CASE WHEN c.F056N = 2024 THEN c.F048N END) / 100, 3) AS `2024财年营业收入(亿美元)`, ROUND((MAX(CASE WHEN c.F056N = 2025 THEN c.F048N END) - MAX(CASE WHEN c.F056N = 2024 THEN c.F048N END)) / NULLIF(MAX(CASE WHEN c.F056N = 2024 THEN c.F048N END), 0) * 100, 2) AS `营业收入同比增长率(%)` FROM AMERICAN_STOCK_MAIN m JOIN VIEW_COM3103_CUM c ON m.FIU_ID = c.FIU_ID WHERE (m.COMB_SYMBOL = 'AAPL.US' OR m.CSNAME LIKE '%苹果%') AND c.F056N IN (2024, 2025) AND c.F003V = 'FY' AND c.F048N IS NOT NULL GROUP BY m.CSNAME, m.COMB_SYMBOL;
